export interface MakerDomainConfig {
  /** Specifies the VPC used for non-EFS traffic. The default value is PublicInternetOnly. */
  appNetworkAccessType?: string | Computed<string>;
  /** The entity that creates and manages the required security groups for inter-app communication in VPCOnly mode. Required when CreateDomain.AppNetworkAccessType is VPCOnly and DomainSettings.RStudioServerProDomainSettings.DomainExecutionRoleArn is provided. */
  appSecurityGroupManagement?: string | Computed<string>;
  /** The mode of authentication that members use to access the domain. */
  authMode: string | Computed<string>;
  /** A collection of settings that apply to spaces of Amazon SageMaker Studio. These settings are specified when the Create/Update Domain API is called. */
  defaultSpaceSettings?: MakerDomain_DefaultSpaceSettings | Computed<MakerDomain_DefaultSpaceSettings>;
  /** A collection of settings that apply to users of Amazon SageMaker Studio. These settings are specified when the CreateUserProfile API is called, and as DefaultUserSettings when the CreateDomain API is called. */
  defaultUserSettings: MakerDomain_DefaultUserSettings | Computed<MakerDomain_DefaultUserSettings>;
  /** A name for the domain. */
  domainName: string | Computed<string>;
  /** A collection of Domain settings. */
  domainSettings?: MakerDomain_DomainSettings | Computed<MakerDomain_DomainSettings>;
  /** Indicates whether a home EFS file system is created for the domain. Set to Disabled to skip EFS creation and reduce domain creation time. */
  homeEfsFileSystemCreation?: string | Computed<string>;
  /** SageMaker uses AWS KMS to encrypt the EFS volume attached to the domain with an AWS managed customer master key (CMK) by default. */
  kmsKeyId?: string | Computed<string>;
  /** The VPC subnets that Studio uses for communication. */
  subnetIds?: string[] | Computed<string[]>;
  /** Indicates whether the tags added to Domain, User Profile and Space entity is propagated to all SageMaker resources. */
  tagPropagation?: string | Computed<string>;
  /** A list of tags to apply to the user profile. */
  tags?: MakerDomain_Tags[] | Computed<MakerDomain_Tags[]>;
  /** The ID of the Amazon Virtual Private Cloud (VPC) that Studio uses for communication. */
  vpcId?: string | Computed<string>;
}

